  "settings.commandline.trustTitle": "Modalità senza token",
  "settings.commandline.trustHint": "Consente allo strumento da riga di comando di connettersi senza autenticarsi.",
  "settings.commandline.trustCaution": "In questa modalità qualsiasi programma sui computer consentiti, compresi gli agenti in esecuzione qui, può controllare Polyth a tuo nome, inclusa l'approvazione delle azioni degli agenti. Le richieste tramite reverse proxy o da browser non sono mai considerate attendibili. Per “rete privata” si intendono gli indirizzi di rete locale (10.x, 172.16–31.x, 192.168.x), non intervalli VPN o reti overlay.",
