  "shellintro.kicker": "Tour dell’interfaccia",
  "shellintro.stepCount": "{step} di {total}",
  "shellintro.steps": "Passaggi del tour",
  "shellintro.goToStep": "Vai al passaggio {step} di {total}",
  "shellintro.start": "Fammi vedere",
  "shellintro.skip": "Salta il tour",
  "shellintro.finish": "Inizia",
  "shellintro.menuEntry": "Tour dell’interfaccia",
  "shellintro.addProjectNow": "Aggiungi un progetto ora",
  "shellintro.addProjectResumeNote": "Il giro riprende quando hai finito.",
  "shellintro.projectReadyTitle": "Il tuo progetto è pronto",
  "shellintro.projectReadyBody": "Eccolo. Finché è selezionato, le nuove chat possono vedere i suoi file e lavorarci. Fai clic su un progetto in questo elenco per passare dall’uno all’altro.",
  "shellintro.projectReadyPhoneBody": "Ora è in questo menu. Finché è selezionato, le nuove chat possono vedere i suoi file e lavorarci. Tocca qui quando vuoi per cambiare progetto.",
  "shellintro.openAppearance": "Apri Aspetto",
  "shellintro.welcomeTitle": "Benvenuto in Polyth",
  "shellintro.welcomeBody": "Puoi iniziare subito: non c’è niente da configurare e non puoi rompere nulla. Questo giro di un minuto ti mostra dove scrivere, dove sono conservate le tue chat e come cambiare le cose più avanti.",
  "shellintro.startTitle": "Inizia proprio qui",
  "shellintro.startBody": "Scrivi ciò che ti serve con parole tue – una domanda, un compito o una bozza – e invia. La risposta compare proprio qui. Le tue chat le vedi solo tu.",
  "shellintro.projectsTitle": "Chat e progetti",
  "shellintro.projectsBody": "Qui sono conservate tutte le tue chat, così puoi tornare a ognuna. Anche i progetti che aggiungerai più avanti compariranno qui, ognuno con le sue chat. Un puntino indica che l’assistente sta lavorando o aspetta la tua risposta.",
  "shellintro.addProjectTitle": "Progetti, quando ti servono",
  "shellintro.addProjectBody": "Non serve per iniziare. Un progetto è semplicemente una cartella con i tuoi file: documenti, foto, un sito web o codice. Aggiungine uno e l’assistente potrà aprire e modificare quei file quando glielo chiedi. (Chi sviluppa può anche collegare un repository Git o un altro computer via SSH.)",
  "shellintro.topRailTitle": "Strumenti in alto",
  "shellintro.topRailBody": "Pulsanti per i tuoi strumenti. Ognuno si apre accanto alla chat, così la conversazione resta in vista.",
  "shellintro.rightRailTitle": "Altri strumenti di lato",
  "shellintro.rightRailBody": "Altri strumenti, compresi i componenti aggiuntivi che installi. Ognuno si apre come pannello laterale; trascina il bordo per allargarlo.",
  "shellintro.toolsTitle": "Strumenti",
  "shellintro.dragTitle": "Metti i pulsanti dove vuoi",
  "shellintro.dragBody": "Trascina un pulsante per spostarlo lungo la sua barra o su un’altra. Per rimuoverlo, trascinalo via e rilascia: potrai riaggiungerlo più tardi. Su un touch screen, tieni prima premuto.",
  "shellintro.customizeTitle": "Funzioni su misura",
  "shellintro.customizeBody": "Apri il menu indicato dalla freccia e attiva la «Modalità modifica»: compare una matita su ogni parte dello schermo, per aggiungere, rimuovere o spostare pulsanti e widget. Il resto è nelle Impostazioni: assistenti e modelli di IA, componenti aggiuntivi (pacchetti) e scorciatoie da tastiera.",
  "shellintro.appearanceTitle": "Un aspetto su misura",
  "shellintro.appearanceBody": "In Impostazioni → Aspetto scegli i colori, la modalità chiara o scura, la dimensione del testo, i caratteri, uno sfondo e altro. Ogni progetto può avere anche un’icona propria.",
  "shellintro.projectsPhoneTitle": "Chat e progetti",
  "shellintro.projectsPhoneBody": "Tocca qui per vedere le tue chat. Anche i progetti che aggiungerai più avanti compariranno qui. Un puntino indica che l’assistente sta lavorando o aspetta la tua risposta.",
  "shellintro.addProjectPhoneBody": "Non serve per iniziare. Un progetto è semplicemente una cartella con i tuoi file: documenti, foto, un sito web o codice. Il pulsante + in quel menu ne aggiunge uno; poi l’assistente potrà aprire e modificare quei file quando glielo chiedi.",
  "shellintro.toolsPhoneTitle": "Strumenti",
  "shellintro.toolsPhoneBody": "Qui ci sono i tuoi strumenti. Ognuno si apre a schermo intero; tocca Indietro per tornare alla chat.",
  "shellintro.customizePhoneBody": "Su un computer, la «Modalità modifica» nel tuo menu ti permette di aggiungere, rimuovere o spostare pulsanti. Anche qui, nelle Impostazioni puoi scegliere assistenti e modelli di IA, componenti aggiuntivi (pacchetti) e altro.",
  "composer.manageHarnesses": "Gestisci gli harness",
  "packages.onboarding.tours.installed.modelsComeFromHarnesses": "I modelli arrivano dai tuoi harness",
  "packages.onboarding.tours.installed.polythTalksToModelsThroughHarnesses": "Polyth parla con i modelli tramite gli harness degli agenti. I modelli gratuiti di OpenCode funzionano senza account. Preferisci Claude Code, Codex o un altro agente? Installa e configura i tuoi preferiti nella pagina Harnesses: è facoltativo.",
  "packages.onboarding.tours.installed.openHarnesses": "Apri Harnesses",
  "desktopupdate.availableTitle": "Polyth {version} è disponibile",
